package com.acromere.transaction;

import lombok.Getter;

/**
 * A single transaction operation that is processed during the commit process
 * and generates a {@link TxnOperationResult result} that is collected and
 * published when the commit successfully completes.
 * <p>
 * Subclasses must implement the {@link #commit()} and {@link #revert()} methods
 * to define the forward and rollback behavior of the operation. Operations are
 * associated with a {@link TxnEventTarget target} that will receive any events
 * generated by the operation.
 */
public abstract class TxnOperation {

	@Getter
	private final TxnEventTarget target;

	@Getter
	private final TxnOperationResult result;

	private TxnOperation.Status status;

	protected TxnOperation( TxnEventTarget target ) {
		this.target = target;
		result = new TxnOperationResult( this );
		status = Status.WAITING;
	}

	/**
	 * Perform the commit logic for this operation. Called during transaction
	 * commit. Subclasses should implement the forward behavior here.
	 *
	 * @return This operation
	 * @throws TxnException if the commit fails
	 */
	protected abstract TxnOperation commit() throws TxnException;

	/**
	 * Perform the revert logic for this operation. Called during transaction
	 * rollback if a subsequent operation in the transaction fails.
	 *
	 * @return This operation
	 * @throws TxnException if the revert fails
	 */
	protected abstract TxnOperation revert() throws TxnException;

	Status getStatus() {
		return status;
	}

	final TxnOperationResult callCommit() throws TxnException {
		try {
			status = Status.COMMITTING;
			commit();
			status = Status.COMMITTED;
		} catch( TxnException exception ) {
			status = Status.FAILED;
			throw exception;
		}
		return getResult();
	}

	final void callRevert() throws TxnException {
		try {
			status = Status.REVERTING;
			revert();
			status = Status.REVERTED;
		} catch( TxnException exception ) {
			status = Status.FAILED;
			throw exception;
		}
	}

	@Override
	public String toString() {
		return getClass().getSimpleName() + "[" + System.identityHashCode( this ) + "]";
	}

	/**
	 * The lifecycle status of a transaction operation.
	 */
	public enum Status {
		/** Operation is waiting to be committed. */
		WAITING,
		/** Operation is currently being committed. */
		COMMITTING,
		/** Operation has been successfully committed. */
		COMMITTED,
		/** Operation is currently being reverted. */
		REVERTING,
		/** Operation has been successfully reverted. */
		REVERTED,
		/** Operation failed during commit or revert. */
		FAILED
	}

}
